"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["84627"],{65242(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.tipo_processo_codigo_obrigatorio","status":422,"titulo":"TipoProcessoCodigo obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.tipo_processo_codigo_obrigatorio","requisitos":["UNI-REQ-0018","UNI-REQ-0098"],"oQueAconteceu":["O campo `tipoProcessoCodigo` n\xe3o veio no corpo da requisi\xe7\xe3o, veio nulo, vazio ou s\xf3 com espa\xe7os. A\\nregra legal sempre diz a que tipo de processo seletivo se aplica: ou o c\xf3digo de um tipo cadastrado e\\nativo, ou `TODOS_OS_TIPOS`, que a torna universal. Omitir o campo n\xe3o equivale a `TODOS_OS_TIPOS`. Nada \xe9 gravado.","A recusa \xe9 de dom\xednio, com status 422, e n\xe3o de leitura do corpo: campo omitido e campo vazio t\xeam o\\nmesmo resultado. A resposta lista todas as viola\xe7\xf5es de campo da mesma requisi\xe7\xe3o em `errors[]`, cada\\numa com o campo em camelCase, o c\xf3digo e a mensagem; o `code` principal da resposta \xe9 o da primeira viola\xe7\xe3o, na\\nordem em que os campos s\xe3o conferidos (tipo de processo, categoria, c\xf3digo da regra, predicado,\\ndescri\xe7\xe3o, base legal, ato normativo, portaria interna e vig\xeancia).","A confer\xeancia vem depois da permiss\xe3o para manter obrigatoriedades legais e da leitura do corpo, e\\nantes de qualquer consulta: na atualiza\xe7\xe3o, antes de a regra ser buscada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)); nas duas opera\xe7\xf5es,\\nantes da confer\xeancia de que o tipo existe e est\xe1 ativo\\n([`tipo_processo_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_nao_encontrado_ou_inativo))."],"comoResolver":["Informe o c\xf3digo de um tipo de processo ativo do m\xf3dulo Configura\xe7\xe3o, com at\xe9 80 caracteres\\n([`tipo_processo_codigo_invalido`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_codigo_invalido)),\\nou `TODOS_OS_TIPOS` para uma regra que vale para todos os tipos. Na atualiza\xe7\xe3o, a regra \xe9 substitu\xedda por inteiro:\\nreenvie tamb\xe9m os campos que n\xe3o mudam, porque o que n\xe3o for enviado \xe9 tratado como ausente."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);